package com.wissfind.marketplace.controller; import com.wissfind.marketplace.entity.Order;import com.wissfind.marketplace.repo.OrderRepository;import com.wissfind.marketplace.service.CurrentUser;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/delivery") public class DeliveryController {final OrderRepository r;public DeliveryController(OrderRepository r){this.r=r;} @GetMapping("/seller") @PreAuthorize("hasRole('SELLER')") public List<Order> seller(){return r.findAll().stream().filter(o->o.seller.id.equals(CurrentUser.id())).toList();} @PatchMapping("/{id}/status") @PreAuthorize("hasAnyRole('SELLER','ADMIN')") public Order status(@PathVariable Long id,@RequestParam String value){var o=r.findById(id).orElseThrow();if(CurrentUser.role().equals("SELLER")&&!o.seller.id.equals(CurrentUser.id()))throw new IllegalArgumentException("Not your shipment");o.deliveryStatus=value;return r.save(o);}}
